import{_ as a,o as e,c as r,a6 as i}from"./chunks/framework.De615z8S.js";const h=JSON.parse('{"title":"完整提示词怎么写","description":"","frontmatter":{"id":"prompt-writing","title":"完整提示词怎么写","chapter":"02","status":"已公开","evidence_status":"方法已整理，未执行图像任务","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":[],"order":12},"headers":[],"relativePath":"start/prompt-writing.md","filePath":"start/prompt-writing.md"}'),o={name:"start/prompt-writing.md"};function s(n,t,p,d,l,_){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="完整提示词怎么写" tabindex="-1">完整提示词怎么写 <a class="header-anchor" href="#完整提示词怎么写" aria-label="Permalink to &quot;完整提示词怎么写&quot;">​</a></h1><p>一条可执行任务词由“任务、输入身份、必须保持、允许修改、画面安排、准确文字、实际输出与检查”组成。模型参数和网站按钮放在工具适配说明中，不混成永远有效的咒语。</p><h2 id="从短词变成任务" tabindex="-1">从短词变成任务 <a class="header-anchor" href="#从短词变成任务" aria-label="Permalink to &quot;从短词变成任务&quot;">​</a></h2><p>“高级感商品图”缺主体依据、使用位置和结果要求。先填清真实商品图、已核实事实、背景与光线、留白位置、比例和文字，再套用<a href="/ai-visual-creation-handbook/prompts/P01">P01</a>。需要一套图时先规划各张职责，逐张完成，而不是把十个目标压到一个生成请求里。</p><p>分析、策划、生图、修图、排版、批量执行应分开写。例如先从事实表规划卖点，再生成背景，再在图层软件排准确文字。没有生图能力的工具可以输出方案，但不能把文字描述当成已生成图片。</p><h2 id="失败后怎么改" tabindex="-1">失败后怎么改 <a class="header-anchor" href="#失败后怎么改" aria-label="Permalink to &quot;失败后怎么改&quot;">​</a></h2><p>记录上一版完整提示词和结果；定位是主体漂移、构图、文字还是光影问题。只修改对应条件，保留其他变量比较。中文文案先逐字确认，再根据市场语言本地化；译文检查由熟悉目标语言的人或独立复核步骤完成。</p>',7)])])}const m=a(o,[["render",s]]);export{h as __pageData,m as default};
